import React, { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom"; 
import Sidebar from "../../components/Sidebar"; 
import HeaderPanel from "../../components/HeaderPanel";
import "../../components/admin.css"; 
import axios from 'axios'; 
import { AuthContext } from "../../context/AuthContext.jsx";  

const API_URL = "http://localhost:3001/api/productos"; 
const CATEGORIAS_URL = "http://localhost:3001/api/categorias"; 
const CLASIFICACIONES_URL = "http://localhost:3001/api/clasificaciones"; 

export default function FormularioProductoNuevo() {
    const { userId } = useContext(AuthContext);
    const navigate = useNavigate(); 

    const [formData, setFormData] = useState({
        nom_producto: '',
        precio_unitario: '',
        stock_actual: '',
        stock_minimo: 1,
        color: '',
        talla: '',
        tamaño: '',
        descripcion: '',
        id_categoria: '',
        id_clasificacion: '',
        observaciones: 'Stock inicial registrado al crear producto.',
        id_usuario: userId || 'Adm-01',
    });

    const [imagen, setImagen] = useState(null);
    const [categorias, setCategorias] = useState([]);
    const [clasificaciones, setClasificaciones] = useState([]);
    const [mensaje, setMensaje] = useState({ text: '', type: '' });
    const [cargando, setCargando] = useState(false);

    // Sincronizar userId
    useEffect(() => {
        console.log(" userId:", userId);
        if (userId) {
            console.log(" userId encontrado, actualizando formData");
            setFormData(prev => ({
                ...prev,
                id_usuario: userId
            }));
        } else {
            console.warn("userId NO encontrado");
            setFormData(prev => ({
                ...prev,
                id_usuario: 'Adm-01' 
            }));
        }
    }, [userId]);

    // Cargar categorías y clasificaciones
    useEffect(() => {
        const fetchExternalData = async () => {
            try {
                const [catRes, clasRes] = await Promise.all([
                    axios.get(CATEGORIAS_URL),
                    axios.get(CLASIFICACIONES_URL),
                ]);
                setCategorias(catRes.data);
                setClasificaciones(clasRes.data);
            } catch (error) {
                console.error("Error al cargar datos externos:", error);
                setMensaje({ text: 'Error al cargar categorías/clasificaciones.', type: 'error' });
            }
        };
        fetchExternalData();
    }, []);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleImageChange = (e) => {
        setImagen(e.target.files[0]);
    };

    const handleReset = () => {
        setFormData({
            nom_producto: '', precio_unitario: '', stock_actual: '', stock_minimo: 1,
            color: '', talla: '', tamaño: '', descripcion: '', 
            id_categoria: '', id_clasificacion: '',
            observaciones: 'Stock inicial registrado al crear producto.',
            id_usuario: userId || '', 
        });
        setImagen(null);
        setMensaje({ text: '', type: '' });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        console.log("Iniciando envío de formulario...");
        console.log("Datos del formulario:", formData);

        setCargando(true);
        setMensaje({ text: '', type: '' });

        // Validación
        if (
            !formData.nom_producto || 
            !formData.precio_unitario || 
            !formData.id_categoria || 
            !formData.id_clasificacion || 
            !formData.stock_actual ||
            !formData.descripcion ||
            formData.stock_minimo === '' || 
            formData.stock_minimo === null
        ) {
            const errorMsg = "Faltan campos obligatorios: Nombre, Precio, Categoría, Clasificación, Stock Inicial, Descripción, o Stock Mínimo.";
            console.error(errorMsg);
            setMensaje({ text: errorMsg, type: 'error' });
            setCargando(false); 
            return;
        }

        if (!formData.id_usuario) {
            const errorMsg = "Error: No se pudo identificar al usuario de la sesión.";
            console.error(errorMsg);
            setMensaje({ text: errorMsg, type: 'error' });
            setCargando(false); 
            return;
        }

        // Crear FormData
        const data = new FormData();

        Object.keys(formData).forEach(key => {
            if (key === 'stock_actual') {
                data.append('cantidad_m', formData[key]);
            } else {
                data.append(key, formData[key]);
            }
        });

        data.append('es_nuevo_producto', 'true');

        if (imagen) {
            data.append('imagen_producto', imagen);
            console.log("Imagen adjunta:", imagen.name);
        }

        try {
            console.log("Enviando petición a:", `${API_URL}/inventario`);

            const response = await axios.post(`${API_URL}/inventario`, data, {
                headers: { 'Content-Type': 'multipart/form-data' },
            });

            console.log("Respuesta exitosa:", response.data);

            setMensaje({ 
                text: response.data.message || `Producto registrado. ID: ${response.data.id_producto}`, 
                type: 'success' 
            });

            handleReset();

            // Navegar después de éxito
            setTimeout(() => {
                navigate('/productos');
            }, 2000);

        } catch (error) {
            console.error(" Error completo:", error);
            console.error(" Response data:", error.response?.data);
            console.error(" Response status:", error.response?.status);

            const errorMessage = error.response?.data?.details || error.response?.data?.error || error.message ||
                "Error al registrar el producto.";

            setMensaje({ text: `${errorMessage}`, type: 'error' });
        } finally {
            setCargando(false);
        }
    };

    // Función para cancelar
    const handleCancel = () => {
        navigate('/productos');
    };

    return (
        <div className="dashboard-layout">
            <Sidebar/>

            <main className="contenido">
                <HeaderPanel title="Registrar Nuevo Producto en Catálogo"/>

                {mensaje.text && (
                    <div className={`alerta ${mensaje.type}`} style={{
                        padding: '15px',
                        marginBottom: '20px',
                        borderRadius: '5px',
                        backgroundColor: mensaje.type === 'success' ? '#d4edda' : '#f8d7da',
                        color: mensaje.type === 'success' ? '#155724' : '#721c24',
                        border: `1px solid ${mensaje.type === 'success' ? '#c3e6cb' : '#f5c6cb'}`
                    }}>
                        {mensaje.text}
                    </div>
                )}

                <section className="cuadro-blanco form-producto">
                    <form className="formulario" onSubmit={handleSubmit}>

                        <h2>Información General y Stock Inicial</h2>

                        <div className="campo">
                            <label htmlFor="nom_producto">Nombre del Producto *</label>
                            <input 
                                type="text" 
                                id="nom_producto" 
                                name="nom_producto" 
                                placeholder="Nombre completo del producto" 
                                required 
                                value={formData.nom_producto} 
                                onChange={handleChange} 
                                disabled={cargando} 
                            />
                        </div>

                        <div className="campo">
                            <label htmlFor="precio_unitario">Precio Unitario (Venta) *</label>
                            <input 
                                type="number" 
                                id="precio_unitario" 
                                name="precio_unitario" 
                                placeholder="Precio al que se venderá" 
                                required 
                                min="0.01" 
                                step="0.01" 
                                value={formData.precio_unitario} 
                                onChange={handleChange} 
                                disabled={cargando} 
                            />
                        </div>

                        <div className="campo-grupo">
                            <div className="campo">
                                <label htmlFor="stock_actual">Stock Inicial (Entrada) *</label>
                                <input 
                                    type="number" 
                                    id="stock_actual" 
                                    name="stock_actual" 
                                    placeholder="Cantidad inicial en inventario" 
                                    required 
                                    min="1" 
                                    value={formData.stock_actual} 
                                    onChange={handleChange} 
                                    disabled={cargando} 
                                />
                            </div>
                            <div className="campo">
                                <label htmlFor="stock_minimo">Stock Mínimo (Alerta) *</label>
                                <input 
                                    type="number" 
                                    id="stock_minimo" 
                                    name="stock_minimo" 
                                    placeholder="Mínimo para alerta" 
                                    required
                                    min="0" 
                                    value={formData.stock_minimo} 
                                    onChange={handleChange} 
                                    disabled={cargando} 
                                />
                            </div>
                        </div>

                        <h2>Clasificación y Atributos</h2>

                        <div className="campo-grupo">
                            <div className="campo">
                                <label htmlFor="id_categoria">Categoría *</label>
                                <select 
                                    id="id_categoria" 
                                    name="id_categoria" 
                                    required 
                                    value={formData.id_categoria} 
                                    onChange={handleChange} 
                                    disabled={cargando}
                                >
                                    <option value="">Seleccione Categoría</option>
                                    {categorias.map(cat => (
                                        <option key={cat.id_categoria} value={cat.id_categoria}>
                                            {cat.nombre_c}
                                        </option>
                                    ))}
                                </select>
                            </div>
                            <div className="campo">
                                <label htmlFor="id_clasificacion">Clasificación *</label>
                                <select 
                                    id="id_clasificacion" 
                                    name="id_clasificacion" 
                                    required
                                    value={formData.id_clasificacion} 
                                    onChange={handleChange} 
                                    disabled={cargando}
                                >
                                    <option value="">Seleccione Clasificación</option>
                                    {clasificaciones.map(clas => (
                                        <option key={clas.id_clasificacion} value={clas.id_clasificacion}>
                                            {clas.nombre_clas}
                                        </option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        <div className="campo">
                            <label htmlFor="imagen_producto">Imagen del Producto (Opcional)</label>
                            <input 
                                type="file" 
                                id="imagen_producto" 
                                name="imagen_producto" 
                                onChange={handleImageChange} 
                                accept="image/*" 
                                disabled={cargando} 
                            />
                        </div>

                        <div className="campo-grupo">
                            <div className="campo">
                                <label htmlFor="color">Color</label>
                                <input 
                                    type="text" 
                                    id="color" 
                                    name="color" 
                                    value={formData.color} 
                                    onChange={handleChange} 
                                    disabled={cargando} 
                                />
                            </div>
                            <div className="campo">
                                <label htmlFor="talla">Talla</label>
                                <input 
                                    type="text" 
                                    id="talla" 
                                    name="talla" 
                                    value={formData.talla} 
                                    onChange={handleChange} 
                                    disabled={cargando} 
                                />
                            </div>
                            <div className="campo">
                                <label htmlFor="tamaño">Tamaño</label>
                                <input 
                                    type="text" 
                                    id="tamaño" 
                                    name="tamaño" 
                                    value={formData.tamaño} 
                                    onChange={handleChange} 
                                    disabled={cargando} 
                                />
                            </div>
                        </div>

                        <div className="campo">
                            <label htmlFor="descripcion">Descripción *</label>
                            <textarea 
                                id="descripcion" 
                                name="descripcion" 
                                placeholder="Detalles completos del producto..." 
                                rows="3" 
                                required
                                value={formData.descripcion} 
                                onChange={handleChange} 
                                disabled={cargando}
                            ></textarea>
                        </div>

                        <div className="campo">
                            <label htmlFor="observaciones">Observaciones de Registro</label>
                            <textarea 
                                id="observaciones" 
                                name="observaciones" 
                                placeholder="Notas sobre el proveedor, factura de compra, etc." 
                                rows="2"
                                value={formData.observaciones}
                                onChange={handleChange}
                                disabled={cargando}
                            ></textarea>
                        </div>

                        <div className="botones">
                            <button 
                                type="submit" 
                                className="btn-guardar" 
                                disabled={cargando}
                            >
                                <i className="fa-solid fa-plus"></i> 
                                {cargando ? 'Registrando...' : 'Registrar Nuevo Producto'}
                            </button>

                            <button 
                                type="button" 
                                className="btn-cancelar"
                                onClick={handleCancel}
                                disabled={cargando}
                            >
                                <i className="fa-solid fa-xmark"></i> Cancelar
                            </button>
                        </div>
                    </form>
                </section>
            </main>
        </div>
    );
}
